// EDIT ME: keywords to pre-filter jobs before spending AI calls on them.
const keywords = [
  "python", "fastapi", "streamlit", "langchain", "machine learning",
  "ai engineer", "backend", "react", "full stack"
];

// Arbeitnow doesn't always return tags/job_types as an array -- sometimes
// it's a string, sometimes missing entirely. Normalize defensively.
function toArray(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === 'string' && val.trim()) return [val];
  return [];
}

const response = $input.first().json;
const jobs = response.data || [];

const matched = jobs.filter(job => {
  const haystack = `${job.title || ''} ${toArray(job.tags).join(' ')} ${toArray(job.job_types).join(' ')}`.toLowerCase();
  return keywords.some(kw => haystack.includes(kw.toLowerCase()));
});

// Cap how many jobs get sent to the AI scoring step each run, to control API usage
const limited = matched.slice(0, 15);

return limited.map(job => ({
  json: {
    slug: job.slug,
    title: job.title,
    company_name: job.company_name,
    description_snippet: (job.description || '').replace(/<[^>]*>/g, ' ').slice(0, 1200),
    url: job.url,
    tags: toArray(job.tags),
    remote: job.remote,
    location: job.location
  }
}));

// Deduplicates jobs across runs using n8n's built-in workflow static data
// (persisted with the workflow -- no external database needed).
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenSlugs) staticData.seenSlugs = [];

const newItems = $input.all().filter(item => !staticData.seenSlugs.includes(item.json.slug));

// Mark these as seen now so they aren't re-scored (and re-alerted) on the next run
newItems.forEach(item => staticData.seenSlugs.push(item.json.slug));

// Keep the seen list from growing forever
if (staticData.seenSlugs.length > 500) {
  staticData.seenSlugs = staticData.seenSlugs.slice(-500);
}

return newItems;

