const raw = $input.item.json.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { score: 0, reason: 'Could not parse AI response' };
}

// Pull the original job fields back in from the pre-AI step (the HTTP
// Request node's output replaced $json with the raw API response).
const job = $('Skip Already Seen').item.json;

return {
  json: {
    ...job,
    score: parsed.score,
    reason: parsed.reason
  }
};
